```python
def retrieve_documents(query: str, top_k: int = 8):
    client = chromadb.PersistentClient(path=str(CHROMA_DIR))
    collection = client.get_collection(COLLECTION_NAME)
    query_embedding = generate_embedding(query)
    disaster = detect_disaster(query)
    candidate_count = max(top_k * 3, 20)

    if disaster:
        results = collection.query(query_embeddings=[query_embedding], n_results=candidate_count, where={"disaster": disaster})
    else:
        results = collection.query(query_embeddings=[query_embedding], n_results=candidate_count)

    candidates = [
        {
            "text": results["documents"][0][i],
            "metadata": results["metadatas"][0][i],
            "distance": results["distances"][0][i]
        }
        for i in range(len(results["documents"][0]))
        if results["distances"][0][i] <= 350
    ]

    selected = []
    document_counts = {}

    for candidate in candidates:
        document = candidate["metadata"]["document"]
        count = document_counts.get(document, 0)
        if count < max(2, top_k // 2):
            selected.append(candidate)
            document_counts[document] = count + 1
        if len(selected) >= top_k:
            break

    return selected
```
